#!/usr/bin/env bash
# Regenerates every cross-language contract. Generated files are committed; CI runs this
# script and fails if it changes anything (contracts are generated, never hand-edited).
#   packages/proto/*.proto  → services/ai/src/lattice/**   (Python + typed .pyi stubs)
#   Rust API types (ts-rs)  → packages/shared-types/src/** (TypeScript)
# The gateway's Rust gRPC code is generated at build time by crates/aibridge/build.rs.
set -euo pipefail
# Byte-order globbing, so the export list is the same on every machine (macOS's default
# collation would sort "Measure" before "MeResponse"; CI's sorts it after).
export LC_ALL=C
cd "$(dirname "$0")/.."
export PATH="$HOME/.cargo/bin:$PATH"

echo "→ Python gRPC stubs"
rm -rf services/ai/src/lattice
mkdir -p services/ai/src/lattice
(
  cd services/ai
  uv run --frozen python -m grpc_tools.protoc -I ../../packages/proto \
    --python_out=src --grpc_python_out=src --mypy_out=src --mypy_grpc_out=src \
    ../../packages/proto/lattice/ai/v1/*.proto
)
for dir in services/ai/src/lattice services/ai/src/lattice/ai services/ai/src/lattice/ai/v1; do
  : > "$dir/__init__.py"
done

echo "→ TypeScript types"
rm -f packages/shared-types/src/generated/*.ts
(cd services/gateway && cargo test --quiet --workspace --lib export_bindings >/dev/null)
{
  echo "// Generated by scripts/gen.sh from the gateway's Rust types (ts-rs). Do not edit."
  for f in packages/shared-types/src/generated/*.ts; do
    name="$(basename "$f" .ts)"
    echo "export type * from \"./generated/${name}\";"
  done
} > packages/shared-types/src/index.ts

echo "✓ contracts regenerated"
